// Link previews (Open Graph + Twitter card) for every page. The images are
// generated by scripts/gen-share-images.mjs (lib/share-images.generated.ts).
import type { Metadata } from "next";
import type { ShopProduct } from "./catalog/index.ts";
import { formatPrice, priceRange } from "./catalog/select.ts";
import { SHARE_IMAGE_SIZE, shareImages } from "./share-images.generated.ts";

export const SITE_URL = "https://mopclothing.com";
export const SITE_NAME = "Modern Orange Pineapple";
/** The site's description: the slogan + the descriptor, as in the Instagram bio (John 10/13). No country-of-printing claim: Printful picks the print facility. */
export const SITE_DESCRIPTION =
  "Escape the ordinary, own a collectible piece of paradise. Art-inspired designs on real cotton, even the all-overs. Made to order · Morro Bay, CA";

const abs = (p: string) => (p.startsWith("http") ? p : `${SITE_URL}${encodeURI(p)}`);

/** Open Graph + Twitter tags for a page; the home image unless the page has its own. */
export function shareMeta({
  title,
  description,
  path,
  image = shareImages.home,
  alt = "Modern Orange Pineapple: art-inspired designs on real cotton",
}: {
  title: string;
  description: string;
  /** The page's own URL path (og:url); left out, the shared URL is used. */
  path?: string;
  image?: string;
  alt?: string;
}): Pick<Metadata, "openGraph" | "twitter"> {
  const images = [{ url: abs(image), width: SHARE_IMAGE_SIZE.width, height: SHARE_IMAGE_SIZE.height, alt, type: "image/jpeg" }];
  return {
    openGraph: {
      type: "website",
      siteName: SITE_NAME,
      locale: "en_US",
      title,
      description,
      ...(path ? { url: abs(path) } : {}),
      images,
    },
    twitter: { card: "summary_large_image", title, description, images: [abs(image)] },
  };
}

/** The first sentence of a product's copy (more if it's very short), as plain text. */
export function firstSentence(copy: string, min = 40): string {
  const para = copy.split(/\n\s*\n/)[0].replace(/\s+/g, " ").trim();
  // a sentence ends at . ! ? followed by a space, except after Mr. / Mrs. / Dr. / St.
  const parts = para.split(/(?<=(?<!\b(?:Mr|Mrs|Ms|Dr|St))[.!?])\s+/);
  let out = "";
  for (const s of parts) {
    out = out ? `${out} ${s}` : s;
    if (out.length >= min) break;
  }
  return out.length > 200 ? `${out.slice(0, 197).trimEnd()}…` : out;
}

/** "Pelican Tee · from $35", "Sky Tee · $50". */
export function productShareTitle(p: Pick<ShopProduct, "title" | "variants">): string {
  const r = priceRange(p);
  if (!r) return p.title;
  return `${p.title} · ${r.min === r.max ? formatPrice(r.min) : `from ${formatPrice(r.min)}`}`;
}

/** The product's colour named in a link (?color=black → "Black"), or undefined. */
export function linkColor(p: Pick<ShopProduct, "options">, color: string | undefined): string | undefined {
  if (!color) return undefined;
  const want = color.trim().toLowerCase();
  return (p.options?.color ?? []).find((c) => c.toLowerCase() === want);
}

/**
 * A shared ?color= link previews that colour (scripts/gen-share-images.mjs makes one image per
 * colour whose photo differs), and its og:url keeps the colour so apps don't fold it back into the
 * default-colour preview. Any other link, or a colour without its own image, gets the product's.
 */
export function productShareMeta(p: ShopProduct, opts: { color?: string } = {}): Pick<Metadata, "openGraph" | "twitter"> {
  const color = linkColor(p, opts.color);
  const colorImage = color ? shareImages[`${p.slug}?color=${color}`] : undefined;
  return shareMeta({
    title: colorImage ? productShareTitle(p).replace(p.title, `${p.title} in ${color}`) : productShareTitle(p),
    description: firstSentence(p.description),
    path: colorImage ? `/${p.slug}?color=${encodeURIComponent(color!)}` : `/${p.slug}`,
    image: colorImage ?? shareImages[p.slug] ?? shareImages.home,
    alt: colorImage ? `${p.title} in ${color}` : p.title,
  });
}
